
from src.bi_agent.data_analyzer import SalesAnalyzer
from src.bi_agent.tool_executor import SalesToolExecutor


# 1. Load the sales dataset
analyzer = SalesAnalyzer("data/sales.csv")
analyzer.load_data()

# 2. Initialize the tool executor
executor = SalesToolExecutor(analyzer)

# 3. Simulate a plan generated by Qwen
test_plan = {
    "objective": "Identify the product with the highest revenue",
    "tools": ["revenue_by_product"],
    "steps": [
        "Calculate revenue by product",
        "Identify the highest-revenue product"
    ]
}

# 4. Execute the plan
results = executor.execute_plan(test_plan)

# 5. Display results
print("\n===== TOOL EXECUTION RESULTS =====")

for tool_name, result in results.items():
    print(f"\nTool: {tool_name}")
    print(result)

print("\n===== TEST COMPLETED =====")
